import { NextResponse } from "next/server";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";

const productSchema=z.object({name:z.string().trim().min(1).max(80),description:z.string().trim().max(200).optional().nullable(),category:z.string().trim().max(60).optional().nullable(),price:z.number().min(.5).max(50000),imagePath:z.string().max(600).optional().nullable()});
async function owner(){const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return {error:"Please log in.",status:401 as const};const db=createAdminClient();const {data:vendor,error}=await db.from("vendors").select("id,is_active").eq("owner_id",user.id).single();if(error||!vendor)return {error:"Shop not found.",status:404 as const};if(!vendor.is_active)return {error:"Pay the setup fee before managing products.",status:403 as const};return {db,vendor};}
export async function GET(){try{const ctx=await owner();if("error" in ctx)return NextResponse.json({error:ctx.error},{status:ctx.status});const {data,error}=await ctx.db.from("products").select("id,name,description,category,price,image_path,is_available,sort_order,created_at,updated_at").eq("vendor_id",ctx.vendor.id).order("sort_order",{ascending:true}).order("created_at",{ascending:true});if(error)throw error;return NextResponse.json({vendorId:ctx.vendor.id,products:data||[]});}catch{return NextResponse.json({error:"Products are unavailable right now."},{status:503});}}
export async function POST(request:Request){try{const ctx=await owner();if("error" in ctx)return NextResponse.json({error:ctx.error},{status:ctx.status});const parsed=productSchema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:parsed.error.issues[0]?.message||"Check the product details."},{status:400});const v=parsed.data;if(v.imagePath&&(!v.imagePath.startsWith(`${ctx.vendor.id}/products/`)||!/^[a-z0-9-]+\.webp$/.test(v.imagePath.split("/").at(-1)||"")))return NextResponse.json({error:"Choose a product photo uploaded to your shop."},{status:400});const {data:last}=await ctx.db.from("products").select("sort_order").eq("vendor_id",ctx.vendor.id).order("sort_order",{ascending:false}).limit(1).maybeSingle();const {data,error}=await ctx.db.from("products").insert({vendor_id:ctx.vendor.id,name:v.name,description:v.description||null,category:v.category||null,price:Math.round(v.price*100)/100,image_path:v.imagePath||null,sort_order:(last?.sort_order||0)+1}).select("id,name,description,category,price,image_path,is_available,sort_order,created_at,updated_at").single();if(error)throw error;return NextResponse.json({product:data},{status:201});}catch{return NextResponse.json({error:"Product could not be saved. Check its details and try again."},{status:400});}}
